char cmp[] = { 0x0f, 0x0b, 0xff };

int main(int argc, char **argv) {
  if (argc < 2) {
    printf("%s FILE", argv[0]);
    return 1;
  }

  int fd = CHK(open, argv[1], O_RDWR);
  uint64_t fsize = CHK(lseek, fd, 0, SEEK_END);
  CHK(lseek, fd, 0, SEEK_SET);
  char *file = (void*)CHK(mmap, 0, fsize, PROT_READ | PROT_WRITE, 
      MAP_SHARED, fd, 0);
  if (file == NULL)
    err(1, "mmap");

  for (uint64_t i = 0; i < fsize - sizeof(cmp); i++) {
    MTRand r;
    if (!memcmp(cmp, file + i, sizeof(cmp))) {
      printf("Found marker at EXE+0x%lx\n", i);
      seedRand(&r, i & 0xfff);
      ((int*)(file + i + 3))[0] ^= genRandLong(&r);
      ((int*)(file + i + 3))[1] ^= genRandLong(&r);
      i += 8 + sizeof(cmp);
    } else if (!memcmp("!!!", file + i, 3)) {
      file[i] = 0;
      file[i + 1] = 5;
      file[i + 2] = 0;
      i += 3;
      printf("Found string at EXE+0x%lx\n", i);
      seedRand(&r, i & 0xfff);
      char *s = file + i;
      while (*s) {
        *s ^= genRandLong(&r) | 0x80;
        //*s ^= rand() | 0x80;
        s++;
      }
    }
  }
}

// PUBLIC DOMAIN
// from here: https://github.com/ESultanik/mtwister
//
/* An implementation of the MT19937 Algorithm for the Mersenne Twister
 * by Evan Sultanik.  Based upon the pseudocode in: M. Matsumoto and
 * T. Nishimura, "Mersenne Twister: A 623-dimensionally
 * equidistributed uniform pseudorandom number generator," ACM
 * Transactions on Modeling and Computer Simulation Vol. 8, No. 1,
 * January pp.3-30 1998.
 *
 * http://www.sultanik.com/Mersenne_twister
 */

#define UPPER_MASK		0x80000000
#define LOWER_MASK		0x7fffffff
#define TEMPERING_MASK_B	0x9d2c5680
#define TEMPERING_MASK_C	0xefc60000

#include "mtwister.h"

/**
* Creates a new random number generator from a given seed.
*/
void seedRand(MTRand* rand, unsigned long seed) {
  /* set initial seeds to mt[STATE_VECTOR_LENGTH] using the generator
   * from Line 25 of Table 1 in: Donald Knuth, "The Art of Computer
   * Programming," Vol. 2 (2nd Ed.) pp.102.
   */
  rand->mt[0] = seed & 0xffffffff;
  for(rand->index=1; rand->index<STATE_VECTOR_LENGTH; rand->index++) {
    rand->mt[rand->index] = (6069 * rand->mt[rand->index-1]) & 0xffffffff;
  }
}

/**
 * Generates a pseudo-randomly generated long.
 */
unsigned long genRandLong(MTRand* rand) {

  unsigned long y;
  static unsigned long mag[2] = {0x0, 0x9908b0df}; /* mag[x] = x * 0x9908b0df for x = 0,1 */
  if(rand->index >= STATE_VECTOR_LENGTH || rand->index < 0) {
    /* generate STATE_VECTOR_LENGTH words at a time */
    int kk, next, m;
    unsigned long tmp[STATE_VECTOR_LENGTH];

    if(rand->index >= STATE_VECTOR_LENGTH+1 || rand->index < 0) {
      seedRand(rand, 4357);
    }

    for (kk = 0; kk < STATE_VECTOR_LENGTH; kk++) tmp[kk] = rand->mt[kk];

    for (kk = 0; kk < STATE_VECTOR_LENGTH; kk++) {
      next = (kk + 1) % STATE_VECTOR_LENGTH;
      m = (kk + STATE_VECTOR_M) % STATE_VECTOR_LENGTH;
      y = (tmp[kk] & UPPER_MASK) | (tmp[next] & LOWER_MASK);
      rand->mt[kk] = rand->mt[m] ^ (y >> 1) ^ mag[y & 0x1];
    }
    rand->index = 0;
  }
  y = rand->mt[rand->index++];
  y ^= (y >> 11);
  y ^= (y << 7) & TEMPERING_MASK_B;
  y ^= (y << 15) & TEMPERING_MASK_C;
  y ^= (y >> 18);
  return y;
}

/**
 * Generates a pseudo-randomly generated double in the range [0..1].
 */
double genRand(MTRand* rand) {
  return((double)genRandLong(rand) / (unsigned long)0xffffffff);
}

